void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = req.get_param("idx");
    if (!idx || idx[0] == '\0') {
        return;
    }

    uint8_t* image_data = NULL;
    size_t image_size = 0;

    if (!database_query_image(idx, &image_data, &image_size)) {
        return;
    }

    if (image_data == NULL || image_size == 0) {
        free(image_data);
        return;
    }

    char* content_type = "application/octet-stream";
    if (image_size > 0) {
        if (image_data[0] == 0x89) {
            content_type = "image/png";
        } else if (image_data[0] == 0x47) {
            content_type = "image/gif";
        } else if (image_data[0] == 0x49 || image_data[0] == 0x4D) {
            content_type = "image/tiff";
        } else if (image_data[0] == 0xFF && image_size > 1 && image_data[1] == 0xD8) {
            content_type = "image/jpeg";
        }
    }

    rep.set_content(image_data, image_size);
    rep.add_header("Content-Type", content_type);
    rep.add_header("Content-Disposition", "attachment");

    free(image_data);
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = webem_request_get_query_variable(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
