    unsigned char* image_data;
    size_t image_size;
    if (!database_get_image_by_id(idx, &image_data, &image_size)) {
        return;
    }

    rep.content = image_data;
    rep.headers["Content-Type"] = "application/octet-stream";
    rep.headers["Content-Disposition"] = "attachment";

    char content_length[32];
    snprintf(content_length, sizeof(content_length), "%zu", image_size);
    rep.headers["Content-Length"] = content_length;

    if (image_size > 0) {
        unsigned char first_byte = image_data[0];
        if (first_byte == 0xFF) {
            rep.headers["Content-Type"] = "image/jpeg";
        } else if (first_byte == 0x89) {
            rep.headers["Content-Type"] = "image/png";
        } else if (first_byte == 0x47) {
            rep.headers["Content-Type"] = "image/gif";
        }
    }
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = webem_request_get_param(&req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned char* image_data = NULL;
    size_t image_size = 0;
    int result = database_get_image_by_id(idx, &image_data, &image_size);
    if (result != 0 || image_data == NULL || image_size == 0) {
        return;
    }

    const char* file_ext = "unknown";
    if (image_data[0] == 0x47) { // GIF
        file_ext = "gif";
    } else if (image_data[0] == 0x89 && image_size > 1 && image_data[1] == 0x50) { // PNG
        file_ext = "png";
    } else if (image_data[0] == 0xFF && image_size > 1 && image_data[1] == 0xD8) { // JPEG
        file_ext = "jpg";
    } else if (image_data[0] == 0x42 && image_size > 1 && image_data[1] == 0x4D) { // BMP
        file_ext = "bmp";
    }

    reply_set_content(&rep, image_data, image_size);
    char content_disposition[256];
    snprintf(content_disposition, sizeof(content_disposition),
             "attachment; filename=floorplan.%s", file_ext);
    reply_set_header(&rep, "Content-Disposition", content_disposition);
}

void handleFloorplanRequest(WebEmSession* session, const request* req, reply* rep) {
    const char* idx = request_get_param(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned char* imageData = database_get_image_by_id(idx);
    if (!imageData) {
        return;
    }

    // Set the image data as the reply content
    reply_set_body(rep, imageData);

    // Determine the file extension based on the first byte
    char* ext = NULL;
    if (imageData[0] == 0xFF) {
        ext = "jpg";
    } else if (imageData[0] == 0x89) {
        ext = "png";
    } else {
        // Default to unknown if not recognized
        ext = "bin";
    }

    // Add the attachment header with the file name and extension
    char filename[64];
    snprintf(filename, sizeof(filename), "floorplan.%s", ext);
    reply_add_header(rep, "Content-Disposition", "attachment", filename);
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = req.get_param("idx");
    if (!idx || idx[0] == '\0') {
        return;
    }

    // Query the database for the image data
    char* imageData = NULL;
    size_t imageDataSize = 0;
    if (!db_get_image_by_id(idx, &imageData, &imageDataSize)) {
        return;
    }

    // Determine the file extension based on the first byte
    const char* fileExt = "unknown";
    if (imageDataSize > 0) {
        if (imageData[0] == '\x89') {
            fileExt = "png";
        } else if (imageData[0] == '\xFF') {
            fileExt = "jpg";
        } else if (imageData[0] == 'G') {
            fileExt = "gif";
        } else {
            fileExt = "bin";
        }
    }

    // Set the reply content and header
    rep.set_content(imageData, imageDataSize);
    char contentDisposition[128];
    snprintf(contentDisposition, sizeof(contentDisposition), "attachment; filename=floorplan.%s", fileExt);
    rep.add_header("Content-Disposition", contentDisposition);

    free(imageData);
}
